// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != actor);
        vm.assume(newOwner != address(c.owner()));
        vm.prank(actor);
        try c.setOwner(newOwner) returns (bool) {}
        catch {}
        assertTrue(c.owner() != newOwner);
    }
}
